1	package checkpointpolicy
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"strings"
8	
9		"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
10		"github.com/entireio/cli/cmd/entire/cli/paths"
11		"github.com/go-git/go-git/v6"
12		"github.com/go-git/go-git/v6/plumbing"
13		"github.com/go-git/go-git/v6/plumbing/object"
14	)
15	
16	const (
17		sha1HexSize   = 40
18		sha256HexSize = 64
19	)
20	
21	const fetchRefName = plumbing.ReferenceName("refs/entire/policies/checkpoint-fetch")
22	
23	var errStopTraversal = errors.New("stop traversal")
24	
25	type Target struct {
26		Remote string
27		Dir    string
28	}
29	
30	type RemoteState struct {
31		Exists bool
32		Hash   plumbing.Hash
33	}
34	
35	func ResolveTarget(ctx context.Context) (Target, error) {
36		dir, err := paths.WorktreeRoot(ctx)
37		if err != nil {
38			return Target{}, fmt.Errorf("resolve worktree root: %w", err)
39		}
40		target, err := remote.FetchURL(ctx, remote.FetchURLOptions{WorktreeRoot: dir})
41		if err != nil {
42			return Target{}, fmt.Errorf("resolve checkpoint remote URL: %w", err)
43		}
44		return Target{Remote: target, Dir: dir}, nil
45	}
46	
47	func CheckRemote(ctx context.Context, target Target) (RemoteState, error) {
48		output, err := remote.LsRemoteInDir(ctx, target.Dir, target.Remote, RefName.String())
49		if err != nil {
50			return RemoteState{}, fmt.Errorf("check remote checkpoint policy ref: %w", err)
51		}
52		fields := strings.Fields(string(output))
53		if len(fields) == 0 {
54			return RemoteState{}, nil
55		}
56		hash, err := parseRemotePolicyHash(fields[0])
57		if err != nil {
58			return RemoteState{}, err
59		}
60		return RemoteState{Exists: true, Hash: hash}, nil
61	}
62	
63	func Sync(ctx context.Context, repo *git.Repository, target Target) (State, error) {
64		local, err := ReadLocal(ctx, repo)
65		if err != nil {
66			return State{}, err
67		}
68	
69		baseline, remoteFound, err := remoteBaseline(ctx, repo, target, local)
70		if err != nil {
71			return State{}, err
72		}
73		if !remoteFound || local.Hash == baseline.Hash {
74			return baseline, nil
75		}
76	
77		if local.Hash.IsZero() {
78			if err := SetRef(repo, RefName, baseline.Hash); err != nil {
79				return State{}, err
80			}
81			baseline.Source = SourceRemote
82			return baseline, nil
83		}
84		localAncestor, err := isAncestorOf(ctx, repo, local.Hash, baseline.Hash)
85		if err != nil {
86			return State{}, err
87		}
88		if localAncestor {
89			if err := SetRef(repo, RefName, baseline.Hash); err != nil {
90				return State{}, err
91			}
92			baseline.Source = SourceRemote
93			return baseline, nil
94		}
95	
96		baselineAncestor, err := isAncestorOf(ctx, repo, baseline.Hash, local.Hash)
97		if err != nil {
98			return State{}, err
99		}
100		if baselineAncestor {
101			local.RemoteHash = baseline.RemoteHash
102			return local, nil
103		}
104	
105		local.Source = SourceLocalDiverged
106		local.RemoteHash = baseline.RemoteHash
107		return local, nil
108	}
109	
110	func remoteBaseline(ctx context.Context, repo *git.Repository, target Target, local State) (State, bool, error) {
111		remoteState, err := CheckRemote(ctx, target)
112		if err != nil {
113			return State{}, false, err
114		}
115		if !remoteState.Exists {
116			return local, false, nil
117		}
118		if local.Hash == remoteState.Hash {
119			local.Source = SourceRemote
120			local.RemoteHash = remoteState.Hash
121			return local, true, nil
122		}
123	
124		fetched, err := fetchRemotePolicy(ctx, repo, target)
125		if err != nil {
126			return State{}, false, err
127		}
128		fetched.RemoteHash = remoteState.Hash
129		return fetched, true, nil
130	}
131	
132	func parseRemotePolicyHash(raw string) (plumbing.Hash, error) {
133		if !isSupportedRemotePolicyHashLength(raw) {
134			return plumbing.ZeroHash, fmt.Errorf("invalid remote checkpoint policy hash %q", raw)
135		}
136		hash, ok := plumbing.FromHex(raw)
137		if !ok {
138			return plumbing.ZeroHash, fmt.Errorf("invalid remote checkpoint policy hash %q", raw)
139		}
140		return hash, nil
141	}
142	
143	func isSupportedRemotePolicyHashLength(raw string) bool {
144		return len(raw) == sha1HexSize || len(raw) == sha256HexSize
145	}
146	
147	func Push(ctx context.Context, target Target) error {
148		refspec := RefName.String() + ":" + RefName.String()
149		result, err := remote.PushWithOptions(ctx, remote.PushOptions{
150			Remote:   target.Remote,
151			RefSpecs: []string{refspec},
152			Dir:      target.Dir,
153		})
154		if err != nil {
155			output := strings.TrimSpace(result.Output)
156			if output == "" {
157				return fmt.Errorf("push checkpoint policy: %w", err)
158			}
159			return fmt.Errorf("push checkpoint policy: %s: %w", output, err)
160		}
161		return nil
162	}
163	
164	func fetchRemotePolicy(ctx context.Context, repo *git.Repository, target Target) (State, error) {
165		refspec := fmt.Sprintf("+%s:%s", RefName, fetchRefName)
166		if _, err := remote.Fetch(ctx, remote.FetchOptions{
167			Remote:   target.Remote,
168			RefSpecs: []string{refspec},
169			NoTags:   true,
170			NoFilter: true,
171			Dir:      target.Dir,
172		}); err != nil {
173			return State{}, fmt.Errorf("fetch checkpoint policy ref: %w", err)
174		}
175		defer removeFetchRef(repo)
176		return ReadFromRef(ctx, repo, fetchRefName, SourceRemote)
177	}
178	
179	func removeFetchRef(repo *git.Repository) {
180		if err := repo.Storer.RemoveReference(fetchRefName); err != nil {
181			return
182		}
183	}
184	
185	func isAncestorOf(ctx context.Context, repo *git.Repository, ancestor, target plumbing.Hash) (bool, error) {
186		if ancestor == target {
187			return true, nil
188		}
189	
190		iter, err := repo.Log(&git.LogOptions{From: target})
191		if err != nil {
192			return false, fmt.Errorf("open checkpoint policy ancestry: %w", err)
193		}
194		defer iter.Close()
195	
196		found := false
197		err = iter.ForEach(func(commit *object.Commit) error {
198			if err := ctx.Err(); err != nil {
199				return fmt.Errorf("checkpoint policy ancestry context: %w", err)
200			}
201			if commit.Hash == ancestor {
202				found = true
203				return errStopTraversal
204			}
205			return nil
206		})
207		if err != nil && !errors.Is(err, errStopTraversal) {
208			return false, fmt.Errorf("traverse checkpoint policy ancestry: %w", err)
209		}
210		return found, nil
211	}
