2	
3	import (
4		"cmp"
5		"fmt"
6		"strings"
7	
8		"golang.org/x/mod/semver"
9	)
10	
11	type CheckpointFamily string
12	
13	const (
14		CheckpointFamilyBranch CheckpointFamily = "branch"
15		CheckpointFamilyRefs   CheckpointFamily = "refs"
16	)
17	
18	type CheckpointFormat struct {
19		Family  CheckpointFamily
20		Version string
21	}
22	
23	func ParseFormat(raw string) (CheckpointFormat, error) {
24		familyRaw, versionRaw, ok := strings.Cut(raw, "-")
25		if !ok || familyRaw == "" || versionRaw == "" {
26			return CheckpointFormat{}, fmt.Errorf("invalid checkpoint format %q", raw)
27		}
28	
29		if !semver.IsValid(versionRaw) {
30			return CheckpointFormat{}, fmt.Errorf("invalid checkpoint version %q", versionRaw)
31		}
32		if semver.Major(versionRaw) == "v0" {
33			return CheckpointFormat{}, fmt.Errorf("invalid checkpoint version %q", versionRaw)
34		}
35		if semver.Build(versionRaw) != "" {
36			return CheckpointFormat{}, fmt.Errorf("checkpoint version %q must not include build metadata", versionRaw)
37		}
38	
39		return CheckpointFormat{Family: CheckpointFamily(familyRaw), Version: semver.Canonical(versionRaw)}, nil
40	}
41	
42	func (f CheckpointFormat) String() string {
43		if f.Family == "" || f.Version == "" {
44			return ""
45		}
46		return fmt.Sprintf("%s-%s", f.Family, f.Version)
47	}
48	
49	func Compare(a, b CheckpointFormat) int {
50		aRank := familyRank(a.Family)
51		bRank := familyRank(b.Family)
52		if aRank != bRank {
53			return cmp.Compare(aRank, bRank)
54		}
55		if a.Family != b.Family {
56			return cmp.Compare(string(a.Family), string(b.Family))
57		}
58		return semver.Compare(a.Version, b.Version)
59	}
60	
61	func CanRead(format CheckpointFormat) bool {
62		return readFormats[format]
63	}
64	
65	func CanWrite(format CheckpointFormat) bool {
66		return writeFormats[format]
67	}
68	
69	func familyRank(family CheckpointFamily) int {
70		if rank, ok := familyRanks[family]; ok {
71			return rank
72		}
73		return len(familyRanks)
74	}
75	
76	var familyRanks = map[CheckpointFamily]int{
77		CheckpointFamilyBranch: 0,
78		CheckpointFamilyRefs:   1,
79	}
80	
81	var branchV1Format = CheckpointFormat{Family: CheckpointFamilyBranch, Version: semver.Canonical("v1")}
82	
83	var (
84		readFormats = map[CheckpointFormat]bool{
85			branchV1Format: true,
86		}
87	
88		writeFormats = map[CheckpointFormat]bool{
89			branchV1Format: true,
90		}
91	)
