3	import (
4		"context"
5		"fmt"
6	
7		"github.com/go-git/go-git/v6"
8	)
9	
10	type UpdateOptions struct {
11		CheckpointVersion    string
12		CheckpointMinVersion string
13		Force                bool
14	}
15	
16	func Update(ctx context.Context, repo *git.Repository, target Target, opts UpdateOptions) (State, error) {
17		baseline, err := updateBaseline(ctx, repo, target)
18		if err != nil {
19			return State{}, err
20		}
21	
22		policy := baseline.Policy
23		if opts.CheckpointVersion != "" {
24			policy.CheckpointVersion = opts.CheckpointVersion
25		}
26		if opts.CheckpointMinVersion != "" {
27			policy.CheckpointMinVersion = opts.CheckpointMinVersion
28		}
29	
30		if err := rejectDowngrades(baseline.Policy, policy, opts); err != nil {
31			return State{}, err
32		}
33		if err := ValidatePolicy(policy); err != nil {
34			return State{}, err
35		}
36	
37		hash, err := WriteLocal(ctx, repo, baseline.Hash, policy)
38		if err != nil {
39			return State{}, err
40		}
41		return State{
42			Policy:     Normalize(policy),
43			Source:     SourceLocal,
44			Hash:       hash,
45			RemoteHash: baseline.RemoteHash,
46		}, nil
47	}
48	
49	func updateBaseline(ctx context.Context, repo *git.Repository, target Target) (State, error) {
50		local, err := ReadLocal(ctx, repo)
51		if err != nil {
52			return State{}, err
53		}
54	
55		baseline, remoteFound, err := remoteBaseline(ctx, repo, target, local)
56		if err != nil {
57			return State{}, err
58		}
59		if !remoteFound || local.Hash == baseline.Hash {
60			return baseline, nil
61		}
62		if local.Hash.IsZero() {
63			return baseline, nil
64		}
65		localAncestor, err := isAncestorOf(ctx, repo, local.Hash, baseline.Hash)
66		if err != nil {
67			return State{}, err
68		}
69		if localAncestor {
70			return baseline, nil
71		}
72		baselineAncestor, err := isAncestorOf(ctx, repo, baseline.Hash, local.Hash)
73		if err != nil {
74			return State{}, err
75		}
76		if baselineAncestor {
77			local.RemoteHash = baseline.RemoteHash
78			return local, nil
79		}
80		return State{}, fmt.Errorf("local checkpoint policy %s diverges from remote %s; push or reconcile the policy before updating", local.Hash, baseline.RemoteHash)
81	}
82	
83	func rejectDowngrades(before, after Policy, opts UpdateOptions) error {
84		before = Normalize(before)
85		after = Normalize(after)
86	
87		if opts.Force {
88			return nil
89		}
90		if opts.CheckpointVersion != "" {
91			if err := rejectFieldDowngrade("checkpoint_version", before.CheckpointVersion, after.CheckpointVersion); err != nil {
92				return err
93			}
94		}
95		if opts.CheckpointMinVersion != "" {
96			if err := rejectFieldDowngrade("checkpoint_min_version", before.CheckpointMinVersion, after.CheckpointMinVersion); err != nil {
97				return err
98			}
99		}
100		return nil
101	}
102	
103	func rejectFieldDowngrade(field, beforeRaw, afterRaw string) error {
104		before, err := ParseFormat(beforeRaw)
105		if err != nil {
106			return fmt.Errorf("%s existing value %q: %w", field, beforeRaw, err)
107		}
108		after, err := ParseFormat(afterRaw)
109		if err != nil {
110			return fmt.Errorf("%s: %w", field, err)
111		}
112		if Compare(after, before) < 0 {
113			return fmt.Errorf("would downgrade %s from %q to %q; pass --force to allow this", field, beforeRaw, afterRaw)
114		}
115		return nil
116	}
