24	
25	// EventPayload represents the data passed to the detached subprocess.
26	// Note: APIKey and Endpoint are intentionally excluded to avoid exposing
27	// them in process listings (ps/top). SendEvent reads them from package-level vars.
28	type EventPayload struct {
29		Event      string         `json:"event"`
30		DistinctID string         `json:"distinct_id"`
31		Properties map[string]any `json:"properties"`
32		Timestamp  time.Time      `json:"timestamp"`
33	}
34	
35	// silentLogger suppresses PostHog log output - expected for CLI best-effort telemetry
36	type silentLogger struct{}
37	
38	func (silentLogger) Logf(_ string, _ ...interface{})   {}
39	func (silentLogger) Debugf(_ string, _ ...interface{}) {}
40	func (silentLogger) Warnf(_ string, _ ...interface{})  {}
41	func (silentLogger) Errorf(_ string, _ ...interface{}) {}
42	
43	// BuildEventPayload constructs the event payload for tracking.
44	// Exported for testing. Returns nil if the payload cannot be built.
45	func BuildEventPayload(cmd *cobra.Command, agent string, isEntireEnabled bool, version string) *EventPayload {
46		if cmd == nil {
47			return nil
48		}
49	
50		// Get machine ID for distinct_id
51		machineID, err := machineid.ProtectedID("entire-cli")
52		if err != nil {
53			return nil
54		}
55	
56		// Collect flag names (not values) for privacy
57		var flags []string
58		cmd.Flags().Visit(func(flag *pflag.Flag) {
59			flags = append(flags, flag.Name)
60		})
61	
62		selectedAgent := agent
63		if selectedAgent == "" {
64			selectedAgent = "auto"
65		}
66	
67		properties := map[string]any{
68			"command":         cmd.CommandPath(),
69			"agent":           selectedAgent,
70			"isEntireEnabled": isEntireEnabled,
71			"cli_version":     version,
72			"os":              runtime.GOOS,
73			"arch":            runtime.GOARCH,
74		}
75	
76		if len(flags) > 0 {
77			properties["flags"] = strings.Join(flags, ",")
78		}
79	
80		return &EventPayload{
81			Event:      "cli_command_executed",
82			DistinctID: machineID,
83			Properties: properties,
84			Timestamp:  time.Now(),
85		}
86	}
87	
88	// TrackCommandDetached tracks a command execution by spawning a detached subprocess.
89	// This returns immediately without blocking the CLI.
90	func TrackCommandDetached(cmd *cobra.Command, agent string, isEntireEnabled bool, version string) {
91		// Check opt-out environment variables
92		if os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
93			return
94		}
95	
96		if cmd == nil {
97			return
98		}
99	
100		if cmd.Hidden {
101			return
102		}
103	
104		payload := BuildEventPayload(cmd, agent, isEntireEnabled, version)
105		if payload == nil {
106			return
107		}
108	
109		if payloadJSON, err := json.Marshal(payload); err == nil {
110			spawnDetachedAnalytics(string(payloadJSON))
111		}
112	}
113	
114	// BuildPluginEventPayload deliberately omits plugin args/flags — only the
115	// allowlisted plugin name is recorded. Returns nil on failure.
116	func BuildPluginEventPayload(pluginName string, isEntireEnabled bool, version string) *EventPayload {
117		if pluginName == "" {
118			return nil
119		}
120	
121		machineID, err := machineid.ProtectedID("entire-cli")
122		if err != nil {
123			return nil
124		}
125	
126		properties := map[string]any{
127			"command":         "entire " + pluginName,
128			"plugin":          pluginName,
129			"isEntireEnabled": isEntireEnabled,
130			"cli_version":     version,
131			"os":              runtime.GOOS,
132			"arch":            runtime.GOARCH,
133		}
134	
135		return &EventPayload{
136			Event:      "cli_plugin_executed",
137			DistinctID: machineID,
138			Properties: properties,
139			Timestamp:  time.Now(),
140		}
141	}
142	
143	// TrackPluginDetached records a plugin invocation. Call sites must gate
144	// on the plugin allowlist — this function does no name filtering itself.
145	func TrackPluginDetached(pluginName string, isEntireEnabled bool, version string) {
146		if os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
147			return
148		}
149	
150		payload := BuildPluginEventPayload(pluginName, isEntireEnabled, version)
151		if payload == nil {
152			return
153		}
154	
155		if payloadJSON, err := json.Marshal(payload); err == nil {
156			spawnDetachedAnalytics(string(payloadJSON))
157		}
158	}
159	
160	// SendEvent processes an event payload in the detached subprocess.
161	// This is called by the hidden __send_analytics command.
162	func SendEvent(payloadJSON string) {
163		var payload EventPayload
164		if err := json.Unmarshal([]byte(payloadJSON), &payload); err != nil {
165			return
166		}
167	
168		// Create PostHog client - no need for fast timeouts since we're detached
169		// Read API key and endpoint from package-level vars (not passed via argv for security)
170		client, err := posthog.NewWithConfig(PostHogAPIKey, posthog.Config{
171			Endpoint:     PostHogEndpoint,
172			Logger:       silentLogger{},
173			DisableGeoIP: posthog.Ptr(true),
174		})
175		if err != nil {
176			return
177		}
178		defer func() {
179			_ = client.Close()
180		}()
181	
182		// Resolve the installed git version best-effort. A missing or failing
183		// git must never block the rest of the telemetry — the property is simply
184		// omitted when it can't be determined.
185		if v := gitVersion(context.Background()); v != "" {
186			if payload.Properties == nil {
187				payload.Properties = map[string]any{}
188			}
189			payload.Properties["git_version"] = v
190		}
191	
192		// Build properties
193		props := posthog.NewProperties()
194		for k, v := range payload.Properties {
195			props.Set(k, v)
196		}
197	
198		//nolint:errcheck // Best effort telemetry - don't block on result
199		_ = client.Enqueue(posthog.Capture{
200			DistinctId: payload.DistinctID,
201			Event:      payload.Event,
202			Properties: props,
203			Timestamp:  payload.Timestamp,
204		})
205	}
206	
207	// gitVersion returns the installed git version (e.g. "2.43.0"), best-effort.
208	// It returns "" when git is absent, the command fails or times out, or the
209	// output cannot be parsed — callers must treat "" as "unknown" and move on.
210	func gitVersion(ctx context.Context) string {
211		ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
212		defer cancel()
213	
214		out, err := exec.CommandContext(ctx, "git", "--version").Output()
215		if err != nil {
216			return ""
217		}
218		return parseGitVersion(string(out))
219	}
220	
221	// parseGitVersion extracts the version token from `git --version` output, which
222	// looks like "git version 2.43.0" (sometimes with a platform suffix such as
223	// "git version 2.39.3 (Apple Git-146)"). Returns "" if the shape is unexpected.
224	func parseGitVersion(out string) string {
225		fields := strings.Fields(out)
226		if len(fields) < 3 || fields[0] != "git" || fields[1] != "version" {
227			return ""
228		}
229		return fields[2]
230	}
